export const getUpcomingPlannedSessions = createServerFn({ method: "GET" })
  .middleware([requireSupabaseAuth])
  .inputValidator((d: unknown) => z.object({ member_id: z.string().uuid() }).parse(d))
  .handler(async ({ data, context }) => {
    await assertCoach(context.userId);
    const today = localDateISO();
    const d = new Date(today + "T00:00:00");
    d.setDate(d.getDate() + 13);
    const pad = (n: number) => String(n).padStart(2, "0");
    const inTwoWeeks = `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
    const { data: rows } = await supabaseAdmin
      .from("planned_sessions")
      .select("id, day_label, planned_date, status, session_id")
      .eq("member_id", data.member_id)
      .gte("planned_date", today)
      .lte("planned_date", inTwoWeeks)
      .in("status", ["planned", "rest"])
      .order("planned_date", { ascending: true });
    return rows ?? [];
  });

export const togglePlannedSessionRest = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .inputValidator((d: unknown) => z.object({ planned_session_id: z.string().uuid() }).parse(d))
  .handler(async ({ data, context }) => {
    await assertCoach(context.userId);
    const { data: row } = await supabaseAdmin
      .from("planned_sessions")
      .select("status")
      .eq("id", data.planned_session_id)
      .single();
    const nextStatus = row?.status === "rest" ? "planned" : "rest";
    await supabaseAdmin
      .from("planned_sessions")
      .update({ status: nextStatus })
      .eq("id", data.planned_session_id);
    return { status: nextStatus };
  });

export const updateMemberNotes = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .inputValidator((d: unknown) =>
    z
      .object({
        member_id: z.string().uuid(),
        coach_private_notes: z.string().max(5000),
      })
      .parse(d),
  )
  .handler(async ({ data, context }) => {
    await assertCoach(context.userId);
    const { error } = await supabaseAdmin
      .from("member_coach_notes")
      .upsert(
        { member_id: data.member_id, notes: data.coach_private_notes },
        { onConflict: "member_id" },
      );
    if (error) throw new Error(error.message);
    return { ok: true };
  });

export const updateMemberProfile = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .inputValidator((d: unknown) =>
    z
      .object({
        member_id: z.string().uuid(),
        first_name: z.string().trim().max(80).optional().nullable(),
        last_name: z.string().trim().max(80).optional().nullable(),
        weight_kg: z.number().min(20).max(400).optional().nullable(),
        height_cm: z.number().int().min(80).max(260).optional().nullable(),
        level: z.string().trim().max(40).optional().nullable(),
        goal: z.string().trim().max(200).optional().nullable(),
        injuries: z.string().trim().max(2000).optional().nullable(),
        planning_week_start_day: z.number().int().min(1).max(7).optional().nullable(),
        log_weight: z.boolean().optional(),
      })
      .parse(d),
  )
  .handler(async ({ data, context }) => {
    await assertCoach(context.userId);

    // 1. profiles (first/last name)
    if (
      data.first_name !== undefined ||
      data.last_name !== undefined ||
      data.planning_week_start_day !== undefined
    ) {
      const patch: {
        first_name?: string | null;
        last_name?: string | null;
        planning_week_start_day?: number | null;
      } = {};
      if (data.first_name !== undefined) patch.first_name = data.first_name || null;
      if (data.last_name !== undefined) patch.last_name = data.last_name || null;
      if (data.planning_week_start_day !== undefined) {
        patch.planning_week_start_day =
          data.planning_week_start_day == null
            ? null
            : normalizeWeekStartsOn(data.planning_week_start_day);
      }
      const { error } = await supabaseAdmin.from("profiles").update(patch).eq("id", data.member_id);
      if (error) throw new Error(error.message);
    }

    // 2. member_profiles upsert
    const mpPatch: {
      weight_kg?: number | null;
      height_cm?: number | null;
      level?: string | null;
      goal?: string | null;
      injuries?: string | null;
    } = {};
    if (data.weight_kg !== undefined) mpPatch.weight_kg = data.weight_kg;
    if (data.height_cm !== undefined) mpPatch.height_cm = data.height_cm;
    if (data.level !== undefined) mpPatch.level = data.level || null;
    if (data.goal !== undefined) mpPatch.goal = data.goal || null;
    if (data.injuries !== undefined) mpPatch.injuries = data.injuries || null;

    if (Object.keys(mpPatch).length > 0) {
      const { data: existing } = await supabaseAdmin
        .from("member_profiles")
        .select("id")
        .eq("user_id", data.member_id)
        .maybeSingle();
      if (existing) {
        const { error } = await supabaseAdmin
          .from("member_profiles")
          .update(mpPatch)
          .eq("user_id", data.member_id);
        if (error) throw new Error(error.message);
      } else {
        const { error } = await supabaseAdmin
          .from("member_profiles")
          .insert({ user_id: data.member_id, ...mpPatch });
        if (error) throw new Error(error.message);
      }
    }

    // 3. optional weight log
    if (data.log_weight && data.weight_kg) {
      const date = localDateISO();
      const { data: existingRows, error: lookupError } = await supabaseAdmin
        .from("weight_logs")
        .select("id")
        .eq("member_id", data.member_id)
        .eq("date", date)
        .order("created_at", { ascending: false })
        .limit(1);
      if (lookupError) throw new Error(lookupError.message);
      const existing = existingRows?.[0];
      const write = existing
        ? await supabaseAdmin
            .from("weight_logs")
            .update({ weight_kg: data.weight_kg })
            .eq("id", existing.id)
        : await supabaseAdmin
            .from("weight_logs")
            .insert({ member_id: data.member_id, weight_kg: data.weight_kg, date });
      if (write.error) throw new Error(write.error.message);
    }

    return { ok: true };
  });

// â”€â”€â”€ ELEVATION PROXY (server-side â†’ no CORS/rate-limit issues) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

export const getElevation = createServerFn({ method: "GET" })
  .middleware([requireSupabaseAuth])
  .inputValidator((d: unknown) => z.object({ locs: z.string().min(1).max(8000) }).parse(d))
  .handler(async ({ data }) => {
    const res = await fetch(
      `https://api.opentopodata.org/v1/srtm30m?locations=${encodeURIComponent(data.locs)}`,
    );
    if (!res.ok) throw new Error(`OpenTopoData ${res.status}`);
    const json = (await res.json()) as { results: Array<{ elevation: number | null }> };
    return { elevations: json.results.map((r) => r.elevation ?? 300) };
  });

