// â”€â”€â”€ PROGRAM FOR CURRENT MEMBER â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

export const getMyAssignedProgram = createServerFn({ method: "GET" })
  .middleware([requireSupabaseAuth])
  .handler(async ({ context }) => {
    const [{ data: assignment }, { data: profile }] = await Promise.all([
      supabaseAdmin
        .from("assignments")
        .select("id, program_id, start_date, end_date, active")
        .eq("member_id", context.userId)
        .eq("active", true)
        .order("start_date", { ascending: false })
        .limit(1)
        .maybeSingle(),
      supabaseAdmin
        .from("profiles")
        .select("planning_week_start_day")
        .eq("id", context.userId)
        .maybeSingle(),
    ]);
    if (!assignment) return { assignment: null, program: null };
    const { data: program } = await supabaseAdmin
      .from("programs")
      .select(
        "id, name, description, duration_weeks, frequency_per_week, objective, level, structure",
      )
      .eq("id", assignment.program_id)
      .maybeSingle();

    // Override weeks with published assignment_weeks (latest adapted version wins)
    if (program) {
      const { data: weeks } = await supabaseAdmin
        .from("assignment_weeks")
        .select("week_number, structure")
        .eq("assignment_id", assignment.id)
        .in("status", ["published", "in_progress", "done"]);
      if (weeks && weeks.length > 0) {
        const base = (program.structure as object | null) ?? {};
        const merged = mergeAssignmentWeeks(base as never, weeks);
        program.structure = { ...base, weeks: merged } as typeof program.structure;
      }
    }

    return {
      assignment,
      program: program ?? null,
      planning_week_start_day: normalizeWeekStartsOn(profile?.planning_week_start_day),
    };
  });

export const deleteProgram = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .inputValidator((d: unknown) => z.object({ id: z.string().uuid() }).parse(d))
  .handler(async ({ data, context }) => {
    await assertCoach(context.userId);
    // Bloque si le programme est encore actif chez un membre (Ã©vite de lui retirer son programme en cours)
    const { count } = await supabaseAdmin
      .from("assignments")
      .select("id", { count: "exact", head: true })
      .eq("program_id", data.id)
      .eq("active", true);
    if (count && count > 0) {
      throw new Error(
        `Programme actif chez ${count} membre(s) â€” change leur programme avant de le supprimer.`,
      );
    }
    await supabaseAdmin.from("assignments").delete().eq("program_id", data.id);
    const { error } = await supabaseAdmin
      .from("programs")
      .delete()
      .eq("id", data.id)
      .eq("coach_id", context.userId);
    if (error) throw new Error(error.message);
    return { ok: true };
  });

export const toggleMemberArchived = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .inputValidator((d: unknown) => z.object({ member_id: z.string().uuid() }).parse(d))
  .handler(async ({ data, context }) => {
    await assertCoach(context.userId);
    const { data: profile } = await supabaseAdmin
      .from("profiles")
      .select("is_archived")
      .eq("id", data.member_id)
      .single();
    const nextArchived = !(profile as any)?.is_archived;
    await supabaseAdmin
      .from("profiles")
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      .update({ is_archived: nextArchived } as any)
      .eq("id", data.member_id);
    if (nextArchived) {
      await supabaseAdmin.auth.admin.updateUserById(data.member_id, {
        ban_duration: "876000h",
      });
    } else {
      await supabaseAdmin.auth.admin.updateUserById(data.member_id, {
        ban_duration: "none",
      });
    }
    return { is_archived: nextArchived };
  });

