export const forceCompleteSession = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .inputValidator((d: unknown) => z.object({ session_id: z.string().uuid() }).parse(d))
  .handler(async ({ data, context }) => {
    await assertCoach(context.userId);

    const [{ data: logs }, { data: efRpe }] = await Promise.all([
      supabaseAdmin
        .from("set_logs")
        .select("weight_kg, reps, rpe")
        .eq("session_id", data.session_id),
      supabaseAdmin
        .from("exercise_feedbacks")
        .select("rpe")
        .eq("session_id", data.session_id)
        .not("rpe", "is", null),
    ]);

    let totalVol = 0;
    let rpeSum = 0;
    let rpeCount = 0;
    (logs ?? []).forEach((l) => {
      if (l.weight_kg && l.reps) totalVol += Number(l.weight_kg) * Number(l.reps);
      if (l.rpe != null) {
        rpeSum += Number(l.rpe);
        rpeCount += 1;
      }
    });
    if (rpeCount === 0) {
      (efRpe ?? []).forEach((f) => {
        if (f.rpe != null) {
          rpeSum += Number(f.rpe);
          rpeCount += 1;
        }
      });
    }

    const { data: session, error: sessionError } = await supabaseAdmin
      .from("sessions")
      .select("id, member_id, session_label, started_at, member_note, status")
      .eq("id", data.session_id)
      .maybeSingle();
    if (sessionError) throw new Error(sessionError.message);
    if (!session) throw new Error("SÃ©ance introuvable");

    const now = new Date().toISOString();
    let durationMinutes: number | null = null;
    if (session?.started_at) {
      const diffMs = Date.now() - new Date(session.started_at).getTime();
      const diffMin = Math.round(diffMs / 60000);
      durationMinutes = diffMin > 0 && diffMin < 240 ? diffMin : null;
    }

    const forcedNote = buildCoachForcedCompletionNote(session.member_note, { coachName: "LÃ©o" });

    const { data: updatedRows, error } = await supabaseAdmin
      .from("sessions")
      .update({
        status: "completed",
        ended_at: now,
        total_volume_kg: totalVol > 0 ? totalVol : null,
        average_rpe: rpeCount > 0 ? Math.round((rpeSum / rpeCount) * 10) / 10 : null,
        duration_minutes: durationMinutes,
        member_note: forcedNote,
        coach_seen: false,
      })
      .eq("id", data.session_id)
      .select("id");

    if (error) throw new Error(error.message);
    if ((updatedRows ?? []).length === 0) throw new Error("Impossible de clÃ´turer cette sÃ©ance");

    await recordMemberAppEvent({
      memberId: session.member_id,
      actorUserId: context.userId,
      actorRole: "coach",
      eventName: "session_force_completed",
      path: `/coach/seance/${data.session_id}`,
      sessionId: data.session_id,
      metadata: {
        sessionLabel: session.session_label,
        previousStatus: session.status,
        durationMinutes,
        setLogCount: logs?.length ?? 0,
        averageRpe: rpeCount > 0 ? Math.round((rpeSum / rpeCount) * 10) / 10 : null,
      },
    });

    return { ok: true };
  });
